CREATE TABLE pms_sale_milestone (id BIGINT NOT NULL AUTO_INCREMENT,uuid BINARY(16) NOT NULL,created_on DATETIME(6),sale_id BIGINT NOT NULL,milestone_type VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,amount DECIMAL(19,2),currency VARCHAR(12),external_reference VARCHAR(120),evidence_document_id BIGINT,notes VARCHAR(1000),occurred_at DATETIME(6) NOT NULL,recorded_by BIGINT NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_sale_milestone_uuid(uuid),KEY idx_sale_milestone_sale(sale_id,milestone_type,status),CONSTRAINT fk_sale_milestone_sale FOREIGN KEY(sale_id) REFERENCES pms_sale_transaction(id),CONSTRAINT chk_sale_milestone_amount CHECK(amount IS NULL OR amount > 0));
